def find_best_product_sorted(query, page_limit=20, max_pages=50):
    best_rating = None
    candidates = []  # (price, product)
    lower_seen = False
    i=0
    while i < max_pages:
        page = api(query=query, sort_by='-rating', page_index=i, page_limit=page_limit)
        print('page', i, 'len', len(page))
        if not page:
            break
        for p in page:
            inv = p.get('inventory_quantity',0) or 0
            rating = p.get('rating',0) or 0
            price = p.get('price', float('inf'))
            try:
                rating = float(rating)
            except:
                rating = 0.0
            try:
                price = float(price)
            except:
                price = float('inf')

            if best_rating is None:
                if inv > 0:
                    best_rating = rating
                    candidates = [(price, p)]
            else:
                if rating < best_rating - EPS:
                    lower_seen = True
                    break
                if abs(rating - best_rating) <= EPS:
                    if inv > 0:
                        candidates.append((price, p))
        if lower_seen:
            break
        i += 1
    if best_rating is None:
        return None
    # choose cheapest among candidates
    candidates_sorted = sorted(candidates, key=lambda x: x[0])
    best_price, best_p = candidates_sorted[0]
    return {'best_rating': best_rating, 'best_price': best_price, 'product': best_p}

